fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap()
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    assert!(q >= 0 && q <= 100, "Quantile percentage must be between 0 and 100");

    if q == 0 {
        return get_min_val(&a);
    } else if q == 100 {
        return get_max_val(&a);
    }

    let sorted = {
        let mut sorted = a.clone();
        sorted.sort();
        sorted
    };

    let index = (q as f64 / 100.0 * (sorted.len() as f64 - 1.0)).round() as usize;
    sorted[index]
}

fn main() {
    let data = vec![3, 1, 4, 1, 5, 9, 2, 6, 5];
    let quantile_0 = nanquantile(data.clone(), 0);
    let quantile_100 = nanquantile(data.clone(), 100);
    let quantile_50 = nanquantile(data.clone(), 50);

    println!("Min (0th quantile): {}", quantile_0);
    println!("Max (100th quantile): {}", quantile_100);
    println!("Median (50th quantile): {}", quantile_50);
}